INSERT INTO public.exam_questions (subject, grade, topic, difficulty, question_type, question_text, options, answer, explanation)
VALUES
('สังคมศึกษา', 'ป.4', '[ส 1.1 ป.4/1] พุทธประวัติ: การประสูติ ตรัสรู้ ปรินิพพาน', 'easy', 'mcq', 'เจ้าชายสิทธัตถะประสูติ ณ สถานที่ใด?', '["ใต้ร่มไม้รัง ลุมพินีวัน","ใต้ต้นพระศรีมหาโพธิ์ พุทธคยา","ป่าอิสิปตนมฤคทายวัน","สาลวโนทยาน เมืองกุสินารา"]'::jsonb, 0, 'เจ้าชายสิทธัตถะประสูติ ณ ลุมพินีวัน (ปัจจุบันอยู่ในประเทศเนปาล) ตรงกับวันขึ้น 15 ค่ำ เดือน 6'),
('สังคมศึกษา', 'ป.4', '[ส 1.1 ป.4/1] เทวทูต 4', 'medium', 'mcq', 'เจ้าชายสิทธัตถะทอดพระเนตรเห็น "เทวทูตทั้ง 4" ทำให้เกิดความเบื่อหน่ายในโลกียวิสัย เทวทูตทั้ง 4 คือข้อใด?', '["คนเกิด, คนแก่, คนเจ็บ, คนรวย","คนเกิด, คนรวย, คนจน, สมณะ","คนแก่, คนเจ็บ, คนตาย, สมณะ","คนเจ็บ, คนตาย, พระราชา, สมณะ"]'::jsonb, 2, 'เทวทูตทั้ง 4 ได้แก่ คนแก่ คนเจ็บ คนตาย และสมณะ ซึ่งทำให้พระองค์คิดหาทางหลุดพ้นจากความทุกข์'),
('สังคมศึกษา', 'ป.4', '[ส 1.1 ป.4/1] การตรัสรู้ของพระพุทธเจ้า', 'easy', 'mcq', 'พระพุทธเจ้าตรัสรู้ความจริงอันประเสริฐ 4 ประการ ซึ่งเรียกว่าอะไร?', '["ไตรลักษณ์","อริยสัจ 4","อิทธิบาท 4","พรหมวิหาร 4"]'::jsonb, 1, 'พระองค์ตรัสรู้อริยสัจ 4 ได้แก่ ทุกข์ (ความไม่สบายกายใจ), สมุทัย (สาเหตุแห่งทุกข์), นิโรธ (การดับทุกข์), มรรค (หนทางดับทุกข์)'),
('สังคมศึกษา', 'ป.4', '[ส 1.1 ป.4/2] พระรัตนตรัย: ดวงแก้ว 3 ประการ', 'easy', 'mcq', 'พระรัตนตรัยอันเป็นที่พึ่งสูงสุดของชาวพุทธ ประกอบด้วยสิ่งใดบ้าง?', '["พระมหากษัตริย์, พระสงฆ์, ประชาชน","พระพุทธ, พระธรรม, พระสงฆ์","พระพรหม, พระอิศวร, พระนารายณ์","ศีล, สมาธิ, ปัญญา"]'::jsonb, 1, 'พระรัตนตรัยคือ แก้ว 3 ประการ ได้แก่ พระพุทธ (ผู้ตรัสรู้), พระธรรม (คำสั่งสอน), และพระสงฆ์ (ผู้ปฏิบัติตามและสืบทอด)'),
('สังคมศึกษา', 'ป.4', '[ส 1.1 ป.4/3] หลักธรรม: เบญจศีล (ศีล 5)', 'easy', 'mcq', 'การไม่พูดโกหก หลอกลวง หรือพูดคำหยาบ ตรงกับการปฏิบัติตามศีลข้อใดในเบญจศีล?', '["ศีลข้อที่ 1","ศีลข้อที่ 2","ศีลข้อที่ 3","ศีลข้อที่ 4"]'::jsonb, 3, 'ศีลข้อที่ 4 (มุสาวาทา เวรมณี) คือการงดเว้นจากการพูดเท็จ พูดคำหยาบ พูดส่อเสียด และพูดเพ้อเจ้อ'),
('สังคมศึกษา', 'ป.4', '[ส 1.1 ป.4/3] หลักธรรม: เบญจธรรม 5', 'medium', 'mcq', 'ธรรมะคู่กับศีลข้อที่ 1 (ไม่ฆ่าสัตว์) ที่สอนให้มีความรัก ความปรารถนาดีต่อผู้อื่น คือข้อใด?', '["เมตตากรุณา","สัมมาอาชีวะ","กามสังวร","สัจจะ"]'::jsonb, 0, 'เมตตากรุณา คือความรักความเห็นอกเห็นใจผู้อื่น เป็นธรรมะที่เกื้อหนุนศีลข้อที่ 1'),
('สังคมศึกษา', 'ป.4', '[ส 1.1 ป.4/4] พุทธสาวก พุทธสาวิกา: พระอุรุเวลกัสสปะ', 'hard', 'mcq', 'พระอุรุเวลกัสสปะ เดิมเคยเป็นผู้นำของนักบวชกลุ่มใดก่อนหันมาบวชในพระพุทธศาสนา?', '["พราหมณ์ผู้บูชาไฟ (ชฎิล 3 พี่น้อง)","ฤๅษีในป่าหิมพานต์","ปริพาชก","โยคีเปลือย"]'::jsonb, 0, 'พระอุรุเวลกัสสปะและน้องๆ เดิมเป็นชฎิลบูชาไฟ มีบริวารรวม 1,000 คน เมื่อฟังธรรมจากพระพุทธเจ้าจึงขอบวช'),
('สังคมศึกษา', 'ป.4', '[ส 1.1 ป.4/5] ชาดก: กุฏิทูสกชาดก (ลิงกับนกกระจอก)', 'medium', 'mcq', 'ชาดกเรื่อง "กุฏิทูสกชาดก" (ลิงเกเรทำลายรังนกกระจอก) ให้ข้อคิดสำคัญเรื่องใด?', '["ไม่ควรสร้างรังบนต้นไม้สูง","การให้คำแนะนำตักเตือนแก่คนพาล ย่อมนำความเดือดร้อนมาสู่ตน","ลิงเป็นสัตว์ที่ฉลาดกว่านก","ควรพึ่งพาอาศัยผู้อื่นเสมอ"]'::jsonb, 1, 'นกกระจอกหวังดีตักเตือนลิงที่เปียกฝน แต่ลิงพาลโกรธจึงทำลายรังนก สอนว่าไม่ควรสั่งสอนคนพาลที่ไม่ยอมรับฟัง'),
('สังคมศึกษา', 'ป.4', '[ส 1.1 ป.4/6] ศาสนาสากล: ศาสนาอิสลาม', 'easy', 'mcq', 'ศาสดาและคัมภีร์ศักดิ์สิทธิ์ของศาสนาอิสลามคือข้อใด?', '["นบีมุฮัมมัด และ คัมภีร์อัลกุรอาน","พระเยซู และ คัมภีร์ไบเบิล","พระพุทธเจ้า และ พระไตรปิฎก","คุรุนานัก และ คัมภีร์อาทิครันถ์"]'::jsonb, 0, 'ศาสนาอิสลามมีนบีมุฮัมมัดเป็นศาสนทูตผู้นำวิวรณ์จากอัลลอฮ์ และมีคัมภีร์อัลกุรอานเป็นคัมภีร์สูงสุด'),
('สังคมศึกษา', 'ป.4', '[ส 1.1 ป.4/6] ศาสนาคริสต์', 'easy', 'mcq', 'ศาสดาของศาสนาคริสต์คือใคร และหลักธรรมสำคัญที่สุดคือเรื่องใด?', '["พระเยซูคริสต์ สอนเรื่องความรักและความเมตตา","โมเสส สอนเรื่องการสู้รบ","พระนารายณ์ สอนเรื่องการอวตาร","พระอินทร์ สอนเรื่องการบำเพ็ญตบะ"]'::jsonb, 0, 'พระเยซูทรงเป็นศาสดาของศาสนาคริสต์ ทรงเน้นหลักความรัก (ความรักต่อพระเจ้าและความรักต่อเพื่อนมนุษย์)'),
('สังคมศึกษา', 'ป.4', '[ส 1.1 ป.4/6] ศาสนาพราหมณ์-ฮินดู', 'medium', 'mcq', 'เทพเจ้าสูงสุด 3 พระองค์ (ตรีมูรติ) ในศาสนาพราหมณ์-ฮินดู ประกอบด้วยเทพองค์ใดบ้าง?', '["พระพรหม, พระวิษณุ (พระนารายณ์), พระศิวะ (พระอิศวร)","พระอินทร์, พระอาทิตย์, พระจันทร์","พระราม, พระลักษณ์, พระพรต","พระพิฆเนศ, พระแม่กาลี, พระแม่ลักษมี"]'::jsonb, 0, 'ตรีมูรติคือมหาเทพ 3 พระองค์: พระพรหม (ผู้สร้าง), พระวิษณุ (ผู้ปกป้อง), และพระศิวะ (ผู้ทำลาย)'),
('สังคมศึกษา', 'ป.4', '[ส 1.2 ป.4/1] วันสำคัญทางศาสนา: วันมาฆบูชา', 'easy', 'mcq', 'วันมาฆบูชา (ขึ้น 15 ค่ำ เดือน 3) มีเหตุการณ์สำคัญใดเกิดขึ้น?', '["พระพุทธเจ้าประสูติ ตรัสรู้ ปรินิพพาน","พระสงฆ์ 1,250 รูปมาประชุมพร้อมกันโดยมิได้นัดหมาย (จาตุรงคสันนิบาต)","พระพุทธเจ้าทรงแสดงปฐมเทศนา","วันถวายพระเพลิงพระพุทธสรีระ"]'::jsonb, 1, 'วันมาฆบูชาเกิดเหตุการณ์จาตุรงคสันนิบาต พระสงฆ์ 1,250 รูปล้วนเป็นพระอรหันต์มาประชุมพร้อมกันโดยมิได้นัดหมาย'),
('สังคมศึกษา', 'ป.4', '[ส 1.2 ป.4/1] วันสำคัญทางศาสนา: วันวิสาขบูชา', 'easy', 'mcq', 'วันวิสาขบูชา (ขึ้น 15 ค่ำ เดือน 6) ได้รับการยกย่องจากองค์การสหประชาชาติ (UN) ให้เป็นวันสำคัญใดของโลก?', '["วันเยาวชนสากล","วันสันติภาพโลก","วันสากลของสหประชาชาติ (International Day)","วันอนุรักษ์สิ่งแวดล้อมโลก"]'::jsonb, 2, 'สหประชาชาติยกย่องวันวิสาขบูชาเป็นวันสำคัญสากลของโลก เนื่องจากเป็นวันคล้ายวันประสูติ ตรัสรู้ และปรินิพพาน'),
('สังคมศึกษา', 'ป.4', '[ส 1.2 ป.4/1] วันอาสาฬหบูชา', 'medium', 'mcq', 'เหตุการณ์สำคัญที่สุดในวันอาสาฬหบูชา (ขึ้น 15 ค่ำ เดือน 8) คือข้อใด?', '["เกิดพระสงฆ์รูปแรกในโลก คือ พระอัญญาโกณฑัญญะ และมีพระรัตนตรัยครบองค์ 3","พระพุทธเจ้าแสดงโอวาทปาติโมกข์","พระพุทธเจ้าเสด็จดับขันธ์ปรินิพพาน","พระมหากัสสปะทำสังคายนาครั้งแรก"]'::jsonb, 0, 'พระพุทธเจ้าทรงแสดงปฐมเทศนา "ธัมมจักกัปปวัตตนสูตร" โปรดปัญจวัคคีย์ ทำให้เกิดพระสงฆ์รูปแรกและมีพระรัตนตรัยครบ 3 ประการ'),
('สังคมศึกษา', 'ป.4', '[ส 1.2 ป.4/2] ศาสนพิธีและการเวียนเทียน', 'easy', 'mcq', 'การเวียนเทียนในวันสำคัญทางพระพุทธศาสนา ต้องเดินเวียนรอบพระอุโบสถในทิศทางใดและกี่รอบ?', '["เวียนซ้าย 1 รอบ","เวียนขวา (ทักษิณาวรรต) 3 รอบ","เวียนซ้าย 3 รอบ","เวียนไปกลับกี่รอบก็ได้"]'::jsonb, 1, 'เดินเวียนขวาตามเข็มนาฬิกา (ประทักษิณ) 3 รอบ พร้อมน้อมรำลึกถึงพระพุทธ พระธรรม และพระสงฆ์'),
('สังคมศึกษา', 'ป.4', '[ส 2.1 ป.4/1] สิทธิเด็ก 4 ประการ: สิทธิที่จะมีชีวิตรอด', 'easy', 'mcq', 'การที่เด็กได้รับการฉีดวัคซีนป้องกันโรคและได้รับอาหารครบ 5 หมู่ จัดอยู่ในสิทธิเด็กด้านใด?', '["สิทธิที่จะมีชีวิตรอด (Survival)","สิทธิที่จะได้รับการปกป้อง (Protection)","สิทธิที่จะได้รับการพัฒนา (Development)","สิทธิที่จะมีส่วนร่วม (Participation)"]'::jsonb, 0, 'สิทธิที่จะมีชีวิตรอด คือสิทธิในการได้รับการเลี้ยงดู ได้รับอาหาร ที่อยู่อาศัย ยารักษาโรค และการดูแลสุขภาพขั้นพื้นฐาน'),
('สังคมศึกษา', 'ป.4', '[ส 2.1 ป.4/1] สิทธิที่จะได้รับการพัฒนา', 'easy', 'mcq', 'การที่เด็กทุกคนต้องได้รับการศึกษาขั้นพื้นฐาน 12 ปีจากรัฐโดยไม่เสียค่าใช้จ่าย ตรงกับสิทธิเด็กข้อใด?', '["สิทธิที่จะมีส่วนร่วม","สิทธิที่จะได้รับการพัฒนา","สิทธิที่จะมีชีวิตรอด","สิทธิเสรีภาพ"]'::jsonb, 1, 'สิทธิที่จะได้รับการพัฒนา ได้แก่ การศึกษา การเรียนรู้ การเล่นกีฬา และการพัฒนาทางอารมณ์และสติปัญญา'),
('สังคมศึกษา', 'ป.4', '[ส 2.1 ป.4/1] สิทธิที่จะได้รับการปกป้องคุ้มครอง', 'medium', 'mcq', 'การกระทำใดเป็นการ "ละเมิดสิทธิเด็ก"?', '["พ่อแม่พาลูกไปเที่ยวพักผ่อนในวันหยุด","คุณครูสอนให้นักเรียนทำการบ้านด้วยตนเอง","การบังคับใช้แรงงานเด็กหรือทำร้ายร่างกายเด็กอย่างทารุณ","โรงเรียนจัดอาหารกลางวันที่มีประโยชน์ให้เด็กรับประทาน"]'::jsonb, 2, 'การใช้แรงงานเด็ก ทำร้าย ทอดทิ้ง หรือแสวงหาประโยชน์โดยมิชอบ ถือเป็นการละเมิดสิทธิเด็กและผิดกฎหมาย'),
('สังคมศึกษา', 'ป.4', '[ส 2.1 ป.4/2] วัฒนธรรมและประเพณีไทย 4 ภาค', 'medium', 'mcq', 'ประเพณี "บุญบั้งไฟ" และ "แห่ผีตาโขน" เป็นประเพณีท้องถิ่นของภาคใดในประเทศไทย?', '["ภาคเหนือ","ภาคกลาง","ภาคตะวันออกเฉียงเหนือ (อีสาน)","ภาคใต้"]'::jsonb, 2, 'ประเพณีบุญบั้งไฟ (ขอฝนจากพญาแถน) และแห่ผีตาโขน (อ.ด่านซ้าย จ.เลย) เป็นเอกลักษณ์ของภาคอีสาน'),
('สังคมศึกษา', 'ป.4', '[ส 2.1 ป.4/2] ประเพณีภาคเหนือ', 'medium', 'mcq', 'ประเพณี "ยี่เป็ง" (ลอยโคมขึ้นสู่ท้องฟ้า) เป็นประเพณีดั้งเดิมของชาวภาคใด?', '["ภาคใต้","ภาคเหนือ (ล้านนา)","ภาคกลาง","ภาคตะวันออก"]'::jsonb, 1, 'ประเพณียี่เป็งเป็นประเพณีลอยกระทงและจุดโคมลอยตามวัฒนธรรมล้านนาในภาคเหนือ'),
('สังคมศึกษา', 'ป.4', '[ส 2.1 ป.4/2] ประเพณีภาคใต้', 'medium', 'mcq', 'ประเพณี "สารทเดือนสิบ" หรือประเพณีชิงเปรต จัดขึ้นเพื่อวัตถุประสงค์ใดในภาคใต้?', '["เพื่อเฉลิมฉลองฤดูเก็บเกี่ยว","เพื่อทำบุญอุทิศส่วนกุศลให้แก่บรรพบุรุษผู้ล่วงลับ","เพื่อขอฝนสำหรับการเกษตร","เพื่อบูชาพระแม่คงคา"]'::jsonb, 1, 'ประเพณีสารทเดือนสิบของภาคใต้เป็นการทำบุญอุทิศส่วนกุศลให้แก่ดวงวิญญาณบรรพบุรุษและเปรต'),
('สังคมศึกษา', 'ป.4', '[ส 2.1 ป.4/3] บทบาทหน้าที่ของสมาชิกที่ดีในครอบครัวและโรงเรียน', 'easy', 'mcq', 'นักเรียนสามารถปฏิบัติตนเป็นสมาชิกที่ดีของโรงเรียนได้อย่างไร?', '["ปฏิบัติตามกฎระเบียบของโรงเรียนและตั้งใจศึกษาเล่าเรียน","มาโรงเรียนสายทุกวันเพื่อหลีกเลี่ยงเข้าแถว","แอบทิ้งขยะใต้โต๊ะเรียน","ทะเลาะวิวาทกับเพื่อนห้องอื่น"]'::jsonb, 0, 'การเคารพกฎระเบียบ ตั้งใจเรียน และช่วยดูแลรักษาความสะอาดเป็นหน้าที่สำคัญของนักเรียนที่ดี'),
('สังคมศึกษา', 'ป.4', '[ส 2.2 ป.4/1] อำนาจอธิปไตย 3 ฝ่าย', 'hard', 'mcq', 'อำนาจอธิปไตยตามรัฐธรรมนูญแห่งราชอาณาจักรไทย แบ่งออกเป็น 3 ฝ่าย คือข้อใด?', '["อำนาจนิติบัญญัติ, อำนาจบริหาร, อำนาจตุลาการ","อำนาจทหาร, อำนาจตำรวจ, อำนาจพลเรือน","อำนาจครู, อำนาจหมอ, อำนาจทนาย","อำนาจรัฐบาล, อำนาจประชาชน, อำนาจเอกชน"]'::jsonb, 0, 'อำนาจอธิปไตยของปวงชนชาวไทย แบ่งเป็น นิติบัญญัติ (รัฐสภาออกกฎหมาย), บริหาร (ครม. บริหารประเทศ), และตุลาการ (ศาลพิพากษาคดี)'),
('สังคมศึกษา', 'ป.4', '[ส 2.2 ป.4/1] สถาบันพระมหากษัตริย์ในระบอบประชาธิปไตย', 'medium', 'mcq', 'ประเทศไทยมีการปกครองระบอบใด?', '["ระบอบสมบูรณาญาสิทธิราชย์","ระบอบประชาธิปไตยอันมีพระมหากษัตริย์ทรงเป็นประมุข","ระบอบสังคมนิยม","ระบอบเผด็จการทหาร"]'::jsonb, 1, 'ประเทศไทยปกครองด้วยระบอบประชาธิปไตยอันมีพระมหากษัตริย์ทรงเป็นประมุข อำนาจอธิปไตยเป็นของปวงชนชาวไทย'),
('สังคมศึกษา', 'ป.4', '[ส 2.2 ป.4/2] การเลือกตั้งผู้นำในระบอบประชาธิปไตย', 'easy', 'mcq', 'การเลือกตั้งหัวหน้าห้องหรือประธานนักเรียน มีประโยชน์อย่างไรต่อนักเรียน?', '["ทำให้นักเรียนไม่ต้องมาโรงเรียน","เป็นการฝึกฝนหลักการประชาธิปไตย การยอมรับเสียงข้างมากและเคารพเสียงข้างน้อย","ทำให้ประธานนักเรียนมีสิทธิ์ทำโทษเพื่อนตามใจชอบ","ช่วยให้นักเรียนมีเงินค่าขนมเพิ่มขึ้น"]'::jsonb, 1, 'การเลือกตั้งในโรงเรียนเป็นการจำลองระบอบประชาธิปไตย สอนให้นักเรียนมีส่วนร่วม ยอมรับเสียงข้างมาก และเคารพความเห็นต่าง'),
('สังคมศึกษา', 'ป.4', '[ส 2.2 ป.4/3] ผู้นำและผู้ตามที่ดี', 'easy', 'mcq', 'คุณสมบัติข้อใดสำคัญที่สุดของ "ผู้นำที่ดี"?', '["สั่งการโดยไม่รับฟังความคิดเห็นของใคร","มีความรับผิดชอบ เสียสละ มีคุณธรรม และรับฟังความคิดเห็นของทุกคน","เอาแต่ใจตนเองเป็นใหญ่","เลือกปฏิบัติเฉพาะเพื่อนสนิทของตนเอง"]'::jsonb, 1, 'ผู้นำที่ดีต้องมีความยุติธรรม มีวิสัยทัศน์ เสียสละเพื่อส่วนรวม และรับฟังความคิดเห็นของสมาชิกทุกคน'),
('สังคมศึกษา', 'ป.4', '[ส 2.2 ป.4/3] คุณสมบัติของผู้ตามที่ดี', 'easy', 'mcq', 'ข้อใดเป็นลักษณะของ "ผู้ตามที่ดี"?', '["คอยขัดขวางการทำงานของกลุ่ม","ให้ความร่วมมือในการทำงาน ปฏิบัติหน้าที่ที่ได้รับมอบหมายด้วยความตั้งใจ","หลบเลี่ยงไม่ยอมช่วยทำงานกลุ่ม","นินทาผู้นำลับหลัง"]'::jsonb, 1, 'ผู้ตามที่ดีต้องมีความรับผิดชอบต่อหน้าที่ ให้ความร่วมมือ และช่วยเสนอแนะแนวทางแก้ปัญหาอย่างสร้างสรรค์'),
('สังคมศึกษา', 'ป.4', '[ส 2.1 ป.4/4] มารยาทไทย', 'easy', 'mcq', 'การแสดงความเคารพต่อคุณครูหรือผู้ใหญ่ด้วยการไหว้ ควรให้ปลายนิ้วชี้จรดตำแหน่งใด?', '["จรดระหว่างคิ้ว","จรดปลายจมูก","จรดคาง","จรดหน้าผาก"]'::jsonb, 1, 'การไหว้ผู้มีพระคุณและครูอาจารย์ (ระดับที่ 2) ให้ปลายนิ้วชี้จรดระหว่างคิ้ว หรือปลายนิ้วชี้จรดปลายจมูก ปลายนิ้วหัวแม่มือจรดปลายคาง ก้มศีรษะลงพอสมควร'),
('สังคมศึกษา', 'ป.4', '[ส 2.1 ป.4/4] การยืนเคารพธงชาติ', 'easy', 'mcq', 'เมื่อได้ยินเสียงเพลงชาติไทยในเวลา 08.00 น. หรือ 18.00 น. ควรปฏิบัติตนอย่างไร?', '["รีบวิ่งหนีออกจากบริเวณนั้น","หยุดยืนตรงด้วยกิริยาสำรวมเพื่อแสดงความเคารพ","ก้มกราบลงกับพื้นทันที","พูดคุยกับเพื่อนตามปกติ"]'::jsonb, 1, 'การหยุดยืนตรงเมื่อได้ยินเสียงเพลงชาติเป็นการแสดงความเคารพต่อชาติ ศาสนา และพระมหากษัตริย์'),
('สังคมศึกษา', 'ป.4', '[ส 2.1 ป.4/2] ภูมิปัญญาท้องถิ่น', 'medium', 'mcq', 'การนำสมุนไพรฟ้าทะลายโจรมาใช้บรรเทาอาการไข้หวัด จัดเป็นภูมิปัญญาไทยในด้านใด?', '["ด้านเกษตรกรรม","ด้านการแพทย์และสาธารณสุขพื้นบ้าน","ด้านศิลปกรรม","ด้านสถาปัตยกรรม"]'::jsonb, 1, 'การนำสมุนไพรมาใช้รักษาโรคเป็นภูมิปัญญาทางการแพทย์และเภสัชกรรมแผนไทยที่สืบทอดกันมา'),
('สังคมศึกษา', 'ป.4', '[ส 3.1 ป.4/1] ปัจจัยการผลิตสินค้าและบริการ 4 ประการ', 'medium', 'mcq', 'ปัจจัยการผลิตในทางเศรษฐศาสตร์ ประกอบด้วย 4 สิ่งคือข้อใด?', '["ที่ดิน, แรงงาน, ทุน, ผู้ประกอบการ","เงิน, รถยนต์, บ้าน, ทองคำ","พ่อค้า, ลูกค้า, ตลาด, ห้างสรรพสินค้า","โรงงาน, เครื่องจักร, เงินสด, บัตรเครดิต"]'::jsonb, 0, 'ปัจจัยการผลิต 4 ชนิดได้แก่ ที่ดิน (ทรัพยากรธรรมชาติ), แรงงาน (กำลังคน), ทุน (เครื่องจักร อุปกรณ์), และผู้ประกอบการ (ผู้รวบรวมปัจจัยมาผลิต)'),
('สังคมศึกษา', 'ป.4', '[ส 3.1 ป.4/1] สินค้าและบริการ', 'easy', 'mcq', 'ข้อใดจัดเป็น "การบริการ" ไม่ใช่สินค้า?', '["สมุดและดินสอ","ขนมปังและนมสด","การตัดผมที่ร้านตัดผม","รองเท้านักเรียน"]'::jsonb, 2, 'สินค้าเป็นสิ่งของที่จับต้องได้ ส่วนการบริการเป็นการอำนวยความสะดวก สร้างความพึงพอใจ เช่น การตัดผม การโดยสารรถประจำทาง'),
('สังคมศึกษา', 'ป.4', '[ส 3.1 ป.4/2] ความต้องการและความจำเป็นในการดำเนินชีวิต', 'medium', 'mcq', 'สิ่งใดจัดเป็น "ปัจจัย 4" ที่มีความจำเป็นขั้นพื้นฐานต่อการดำรงชีวิตของมนุษย์?', '["โทรศัพท์มือถือราคาแพง","อาหาร, เครื่องนุ่งห่ม, ที่อยู่อาศัย, ยารักษาโรค","รถยนต์หรูหรา","เครื่องประดับเพชรพลอย"]'::jsonb, 1, 'ปัจจัย 4 ได้แก่ อาหาร ที่อยู่อาศัย เครื่องนุ่งห่ม และยารักษาโรค เป็นสิ่งจำเป็นที่มนุษย์ขาดไม่ได้เพื่อความอยู่รอด'),
('สังคมศึกษา', 'ป.4', '[ส 3.1 ป.4/2] การใช้จ่ายเงินอย่างคุ้มค่า', 'easy', 'mcq', 'พฤติกรรมการใช้จ่ายเงินของใครเหมาะสมและเกิดประโยชน์สูงสุด?', '["แก้วซื้อของเล่นใหม่ทุกครั้งที่เห็นโฆษณา","กล้าทำบัญชีรายรับ-รายจ่าย และแบ่งเงินส่วนหนึ่งไว้หยอดกระปุกออมสิน","ก้อยยืมเงินเพื่อนมาซื้อขนมราคาแพง","กิ่งซื้อของที่ไม่จำเป็นเพราะเห็นว่าลดราคา"]'::jsonb, 1, 'การทำบัญชีรายรับ-รายจ่าย ช่วยควบคุมการใช้จ่าย และการแบ่งเงินออมเป็นพฤติกรรมทางการเงินที่ดี'),
('สังคมศึกษา', 'ป.4', '[ส 3.1 ป.4/3] หน้าที่และประโยชน์ของการออมเงิน', 'easy', 'mcq', 'ประโยชน์ที่สำคัญที่สุดของการ "ออมเงิน" คือข้อใด?', '["มีเงินสำรองไว้ใช้ในยามเจ็บป่วยหรือเหตุฉุกเฉิน และใช้เพื่อการศึกษาในอนาคต","เพื่ออวดเพื่อนว่ามีเงินในกระเป๋าเยอะ","เพื่อนำไปซื้อของฟุ่มเฟือยทั้งหมดในวันเดียว","เพื่อไม่ต้องทำงานในอนาคต"]'::jsonb, 0, 'เงินออมช่วยสร้างความมั่นคงในชีวิต มีเงินใช้เมื่อเกิดเหตุจำเป็น และสามารถนำไปต่อยอดอนาคตได้'),
('สังคมศึกษา', 'ป.4', '[ส 3.1 ป.4/3] สถาบันการเงิน: ธนาคาร', 'medium', 'mcq', 'หน้าที่หลักของ "ธนาคารพาณิชย์" คือข้อใด?', '["พิมพ์ธนบัตรออกใช้ในประเทศ","รับฝากเงินและให้กู้ยืมเงิน","ควบคุมราคาสินค้าในตลาด","แจกเงินฟรีให้ประชาชนทุกคน"]'::jsonb, 1, 'ธนาคารมีหน้าที่รับฝากเงิน (จ่ายดอกเบี้ยเงินฝาก) และนำเงินไปให้บุคคลหรือธุรกิจกู้ยืม (คิดดอกเบี้ยเงินกู้)'),
('สังคมศึกษา', 'ป.4', '[ส 3.1 ป.4/3] ธนาคารแห่งประเทศไทย (ธปท.)', 'hard', 'mcq', 'หน่วยงานใดทำหน้าที่เป็น "ธนาคารกลาง" ของประเทศ มีอำนาจพิมพ์ธนบัตรและดูแลเสถียรภาพทางการเงิน?', '["ธนาคารออมสิน","ธนาคารแห่งประเทศไทย","ธนาคารกรุงไทย","กระทรวงการคลัง"]'::jsonb, 1, 'ธนาคารแห่งประเทศไทย (แบงก์ชาติ) เป็นธนาคารกลาง ทำหน้าที่ออกธนบัตรและกำกับดูแลระบบสถาบันการเงินของประเทศ'),
('สังคมศึกษา', 'ป.4', '[ส 3.2 ป.4/1] ความหมายของสหกรณ์', 'medium', 'mcq', '"สหกรณ์" หมายถึงข้อใดในทางเศรษฐกิจ?', '["องค์กรที่ตั้งขึ้นเพื่อแสวงหากำไรสูงสุดจากสมาชิก","การรวมกลุ่มของบุคคลด้วยความสมัครใจ เพื่อช่วยเหลือเกื้อกูลกันทางเศรษฐกิจและสังคม","ห้างสรรพสินค้าขนาดใหญ่ของรัฐบาล","บริษัทที่ผูกขาดการค้าเพียงรายเดียว"]'::jsonb, 1, 'สหกรณ์คือการรวมกลุ่มกันโดยสมัครใจ ดำเนินงานตามหลักประชาธิปไตย เพื่อช่วยเหลือซึ่งกันและกัน ไม่ได้มุ่งแสวงหากำไรสูงสุด'),
('สังคมศึกษา', 'ป.4', '[ส 3.2 ป.4/1] หลักการสำคัญของสหกรณ์', 'hard', 'mcq', 'ข้อใด "ไม่ใช่" หลักการดำเนินงานของสหกรณ์?', '["การเป็นสมาชิกโดยสมัครใจและเปิดกว้าง","การควบคุมตามแนวทางประชาธิปไตย (1 คน 1 เสียง)","สมาชิกที่ถือหุ้นมากที่สุดมีสิทธิ์สั่งการเพียงคนเดียว","การจัดสรรผลประโยชน์หรือเงินปันผลอย่างเป็นธรรม"]'::jsonb, 2, 'ในสหกรณ์ สมาชิกทุกคนมีสิทธิ์ออกเสียงเท่ากันคนละ 1 เสียง ไม่ว่าจะถือหุ้นมากหรือน้อย ต่างจากบริษัทจำกัด'),
('สังคมศึกษา', 'ป.4', '[ส 3.2 ป.4/2] สหกรณ์ในโรงเรียน', 'easy', 'mcq', 'ร้านค้าสหกรณ์ในโรงเรียนมีประโยชน์ต่อนักเรียนอย่างไร?', '["จำหน่ายอุปกรณ์การเรียนและขนมที่มีคุณภาพในราคายุติธรรม และสมาชิกได้รับเงินปันผล","แจกสิ่งของฟรีให้นักเรียนทุกคนทุกวัน","จำหน่ายสินค้าแพงกว่าร้านค้าทั่วไป","บังคับให้นักเรียนต้องซื้อสินค้าทุกคน"]'::jsonb, 0, 'ร้านสหกรณ์โรงเรียนจำหน่ายอุปกรณ์การศึกษาในราคายุติธรรม และเมื่อสิ้นปีการศึกษาจะมีเงินปันผลตามยอดการซื้อให้สมาชิก'),
('สังคมศึกษา', 'ป.4', '[ส 3.1 ป.4/1] ผู้ผลิตและผู้บริโภค', 'easy', 'mcq', 'ชาวสวนปลูกส้มแล้วนำส้มไปขายที่ตลาด ชาวสวนทำหน้าที่ใดในระบบเศรษฐกิจ?', '["ผู้ผลิต","ผู้บริโภค","นายธนาคาร","ผู้ตรวจสอบ"]'::jsonb, 0, 'ผู้ผลิตคือผู้นำปัจจัยการผลิตมาแปรรูปเป็นสินค้าหรือบริการ ส่วนผู้ที่ซื้อไปรับประทานคือผู้บริโภค'),
('สังคมศึกษา', 'ป.4', '[ส 3.1 ป.4/2] สิทธิของผู้บริโภค', 'medium', 'mcq', 'เมื่อนักเรียนซื้อนมกล่องแล้วพบว่านมบูดก่อนวันหมดอายุ นักเรียนควรทำอย่างไรเป็นอันดับแรก?', '["ดื่มต่อไปเพราะเสียดายเงิน","นำหลักฐานใบเสร็จและกล่องนมไปแจ้งร้านค้าเพื่อขอเปลี่ยนหรือคืนเงิน","โพสต์ด่าทอเจ้าของร้านลงโซเชียลมีเดีย","ทิ้งไปโดยไม่บอกใคร"]'::jsonb, 1, 'ผู้บริโภคมีสิทธิได้รับการชดเชยความเสียหายตามกฎหมายคุ้มครองผู้บริโภค จึงควรติดต่อร้านค้าพร้อมหลักฐานทันที'),
('สังคมศึกษา', 'ป.4', '[ส 3.1 ป.4/1] การแข่งขันทางการค้า', 'medium', 'mcq', 'เมื่อมีผู้ขายสินค้าชนิดเดียวกันหลายๆ ร้านในตลาด จะส่งผลดีต่อผู้บริโภคอย่างไร?', '["สินค้ามีราคาแพงขึ้น","ผู้บริโภคมีตัวเลือกมากขึ้น และได้สินค้าที่มีคุณภาพในราคาที่เหมาะสม","สินค้าในตลาดขาดแคลน","ผู้บริโภคต้องจ่ายภาษีเพิ่ม"]'::jsonb, 1, 'การแข่งขันทำให้ผู้ขายต้องพัฒนาคุณภาพสินค้าและตั้งราคาที่เหมาะสม เป็นธรรมต่อผู้บริโภค'),
('สังคมศึกษา', 'ป.4', '[ส 3.1 ป.4/2] การบันทึกรายรับ-รายจ่าย', 'easy', 'mcq', 'สิ่งใดจัดเป็น "รายรับ" ของนักเรียน?', '["เงินค่าขนมที่คุณพ่อให้","เงินค่าซื้อสมุดและปากกา","เงินค่าโดยสารรถประจำทาง","เงินบริจาคช่วยงานโรงเรียน"]'::jsonb, 0, 'เงินที่ได้มา เช่น เงินค่าขนม รางวัล เงินช่วยทำงาน จัดเป็นรายรับ ส่วนเงินที่จ่ายออกไปจัดเป็นรายจ่าย'),
('สังคมศึกษา', 'ป.4', '[ส 3.1 ป.4/3] ปรัชญาเศรษฐกิจพอเพียง', 'medium', 'mcq', 'หลัก 3 ห่วง ในปรัชญาเศรษฐกิจพอเพียงของรัชกาลที่ 9 ประกอบด้วยสิ่งใดบ้าง?', '["พอประมาณ, มีเหตุผล, มีภูมิคุ้มกันในตัวที่ดี","ร่ำรวย, ประหยัด, ตระหนี่","มีเงิน, มีทอง, มีที่ดิน","ทำบุญ, รักษาศีล, ภาวนา"]'::jsonb, 0, 'เศรษฐกิจพอเพียงประกอบด้วย 3 ห่วง: ความพอประมาณ, ความมีเหตุผล, การมีภูมิคุ้มกันที่ดี ภายใต้เงื่อนไขความรู้และคุณธรรม'),
('สังคมศึกษา', 'ป.4', '[ส 5.1 ป.4/1] แผนที่และเครื่องมือทางภูมิศาสตร์', 'easy', 'mcq', 'สัญลักษณ์รูป "สามเหลี่ยมสีดำ" บนแผนที่ภูมิประเทศ มักใช้แทนสิ่งใด?', '["แม่น้ำลำคลอง","ยอดเขาหรือภูเขา","สนามบิน","โรงพยาบาล"]'::jsonb, 1, 'สัญลักษณ์สามเหลี่ยมบนแผนที่ใช้แสดงยอดเขาหรือจุดที่มีระดับความสูงเด่น'),
('สังคมศึกษา', 'ป.4', '[ส 5.1 ป.4/1] ทิศหลักในแผนที่', 'easy', 'mcq', 'โดยทั่วไป ทิศที่อยู่ "ด้านบนสุด" ของแผนที่สากลคือทิศใด?', '["ทิศตะวันออก","ทิศตะวันตก","ทิศใต้","ทิศเหนือ"]'::jsonb, 3, 'ตามมาตรฐานสากล ด้านบนของแผนที่จะกำหนดให้เป็นทิศเหนือเสมอ เว้นแต่จะมีลูกศรบอกทิศกำกับไว้เป็นอย่างอื่น'),
('สังคมศึกษา', 'ป.4', '[ส 5.1 ป.4/1] มาตราส่วนในแผนที่', 'medium', 'mcq', 'มาตราส่วน 1 : 50,000 หมายความว่าอย่างไร?', '["ระยะทางในแผนที่ 1 เซนติเมตร เท่ากับระยะทางจริงบนพื้นโลก 50,000 เซนติเมตร (500 เมตร)","ระยะทางจริง 1 เมตร เท่ากับในแผนที่ 50,000 เมตร","แผนที่นี้ย่อส่วนลง 50 เท่า","ในแผนที่มีภูเขา 50,000 ลูก"]'::jsonb, 0, 'มาตราส่วนแบบสัดส่วน 1 : 50,000 หมายถึง 1 หน่วยในแผนที่ เท่ากับ 50,000 หน่วยในพื้นที่จริงบนโลก'),
('สังคมศึกษา', 'ป.4', '[ส 5.1 ป.4/1] ลูกโลกจำลอง', 'easy', 'mcq', 'เครื่องมือทางภูมิศาสตร์ชนิดใดที่แสดงรูปทรงสัณฐานกลมของโลกและความเอียงของแกนโลกได้สมจริงที่สุด?', '["แผนที่แบน","ลูกโลกจำลอง (Globe)","เข็มทิศ","ภาพถ่ายดาวเทียมแบบสองมิติ"]'::jsonb, 1, 'ลูกโลกจำลองย่อส่วนโลกในลักษณะสามมิติ แสดงความเอียงของแกนโลก 23.5 องศา และสัดส่วนทวีปมหาสมุทรได้ถูกต้องตามจริง'),
('สังคมศึกษา', 'ป.4', '[ส 5.1 ป.4/2] ลักษณะทางกายภาพของประเทศไทย', 'medium', 'mcq', 'ภูมิภาคใดของประเทศไทยที่มีลักษณะภูมิประเทศส่วนใหญ่เป็น "ทิวเขาสูงสลับซับซ้อนและหุบเขา"?', '["ภาคกลาง","ภาคเหนือ","ภาคตะวันออกเฉียงเหนือ","ภาคใต้"]'::jsonb, 1, 'ภาคเหนือของไทยประกอบด้วยเทือกเขาสูงสลับซับซ้อน เป็นต้นกำเนิดของแม่น้ำสายสำคัญ เช่น ปิง วัง ยม น่าน'),
('สังคมศึกษา', 'ป.4', '[ส 5.1 ป.4/2] ลักษณะภูมิประเทศภาคกลาง', 'easy', 'mcq', 'ลักษณะเด่นของภูมิประเทศใน "ภาคกลาง" คือข้อใด?', '["ที่ราบลุ่มแม่น้ำกว้างใหญ่ ดินตะกอนอุดมสมบูรณ์ เหมาะแก่การทำนาปลูกข้าว","ที่ราบสูงดินปนทราย","ภูเขาหินปูนและเกาะแก่งกลางทะเล","ป่าดิบชื้นฝนตกชุกตลอดปี"]'::jsonb, 0, 'ภาคกลางเป็นที่ราบลุ่มดินดอนสามเหลี่ยมปากแม่น้ำ มีแม่น้ำเจ้าพระยาไหลผ่าน เป็นแหล่งปลูกข้าวและเกษตรกรรมสำคัญของประเทศ'),
('สังคมศึกษา', 'ป.4', '[ส 5.1 ป.4/2] ลักษณะภูมิประเทศภาคอีสาน', 'medium', 'mcq', 'ภาคตะวันออกเฉียงเหนือมีลักษณะภูมิประเทศเป็น "ที่ราบสูง" ที่เรียกว่าอะไร?', '["ที่ราบสูงโคราช","ที่ราบสูงทิเบต","ที่ราบสูงเดกกัน","ที่ราบสูงไซบีเรีย"]'::jsonb, 0, 'ภาคอีสานตั้งอยู่บนที่ราบสูงโคราชและแอ่งสกลนคร ลักษณะคล้ายกระทะหงาย ดินส่วนใหญ่เป็นดินทรายเก็บน้ำได้น้อย'),
('สังคมศึกษา', 'ป.4', '[ส 5.1 ป.4/2] ลักษณะภูมิอากาศและลมมรสุม', 'hard', 'mcq', 'ลมมรสุมที่พัดพาความชื้นจากมหาสมุทรอินเดียเข้ามา ทำให้ประเทศไทยมีฝนตกชุก คือลมมรสุมใด?', '["ลมมรสุมตะวันออกเฉียงเหนือ","ลมมรสุมตะวันตกเฉียงใต้","ลมบก","ลมทะเล"]'::jsonb, 1, 'ลมมรสุมตะวันตกเฉียงใต้พัดผ่านทะเลอันดามันนำความชื้นมาทำให้เกิดฤดูฝนในไทย ส่วนลมมรสุมตะวันออกเฉียงเหนือนำความหนาวเย็นและแห้งแล้งเข้ามา'),
('สังคมศึกษา', 'ป.4', '[ส 5.2 ป.4/1] ทรัพยากรธรรมชาติในท้องถิ่น', 'easy', 'mcq', 'ทรัพยากรธรรมชาติในข้อใดจัดเป็นทรัพยากรที่ "ใช้แล้วไม่หมดสิ้น"?', '["น้ำมันดิบ","ถ่านหิน","แสงอาทิตย์และลม","ก๊าซธรรมชาติ"]'::jsonb, 2, 'แสงอาทิตย์ ลม และน้ำ หมุนเวียนตามธรรมชาติจึงใช้ไม่มีวันหมด ต่างจากเชื้อเพลิงฟอสซิลที่ใช้แล้วหมดไป'),
('สังคมศึกษา', 'ป.4', '[ส 5.2 ป.4/2] ปัญหาสิ่งแวดล้อม: มลพิษทางอากาศ', 'medium', 'mcq', 'ฝุ่นละอองขนาดเล็ก PM 2.5 ในประเทศไทย มักมีสาเหตุหลักมาจากการกระทำใด?', '["การปลูกต้นไม้ในเมือง","การเผาเศษวัชพืชทางการเกษตร ควันไอเสียรถยนต์ และโรงงานอุตสาหกรรม","การใช้พลังงานแสงอาทิตย์","การคัดแยกขยะในครัวเรือน"]'::jsonb, 1, 'PM 2.5 เกิดจากการเผาในที่โล่ง ควันไอเสียจากเครื่องยนต์ดีเซล และการปล่อยควันจากโรงงานอุตสาหกรรม'),
('สังคมศึกษา', 'ป.4', '[ส 5.2 ป.4/2] การอนุรักษ์ทรัพยากรดินและน้ำ', 'medium', 'mcq', 'การปลูก "หญ้าแฝก" ตามแนวพระราชดำริ มีประโยชน์ต่อดินอย่างไร?', '["ช่วยดูดซับสารพิษทำให้พืชโตเร็ว","รากหญ้าแฝกที่ยาวและหนาแน่นช่วยยึดเกาะดิน ป้องกันการชะล้างพังทลายของหน้าดิน","ช่วยเร่งให้ดินกลายเป็นหิน","ใช้เป็นอาหารสัตว์ทดแทนหญ้าธรรมดา"]'::jsonb, 1, 'หญ้าแฝกมีระบบรากลึกและแน่นหนา ทำหน้าที่เป็นกำแพงธรรมชาติช่วยยึดหน้าดินและกักเก็บความชุ่มชื้น'),
('สังคมศึกษา', 'ป.4', '[ส 5.2 ป.4/3] การลดปริมาณขยะตามหลัก 3R', 'easy', 'mcq', 'การนำถุงผ้าไปใส่ของแทนการใช้ถุงพลาสติก ตรงกับหลัก 3R ข้อใด?', '["Reduce (ลดการใช้)","Reuse (นำกลับมาใช้ซ้ำ)","Recycle (แปรรูปนำกลับมาใช้ใหม่)","Repair (ซ่อมแซม)"]'::jsonb, 0, 'Reduce คือการลดการใช้สิ่งของที่สร้างขยะหรือใช้ครั้งเดียวทิ้ง เช่น การปฏิเสธถุงพลาสติกแล้วใช้ถุงผ้าแทน'),
('สังคมศึกษา', 'ป.4', '[ส 5.2 ป.4/3] การคัดแยกขยะ', 'easy', 'mcq', 'ถังขยะ "สีแดง" ตามมาตรฐานสากล ใช้สำหรับทิ้งขยะประเภทใด?', '["ขยะเปียก (เศษอาหาร)","ขยะรีไซเคิล (ขวดแก้ว กระดาษ)","ขยะอันตราย (หลอดไฟ แบตเตอรี่ กระป๋องสเปรย์)","ขยะทั่วไป (ถุงพลาสติก ซองขนม)"]'::jsonb, 2, 'ถังขยะสีแดงใช้สำหรับขยะอันตรายและสารพิษ เช่น ถ่านไฟฉาย หลอดฟลูออเรสเซนต์ แบตเตอรี่'),
('สังคมศึกษา', 'ป.4', '[ส 5.2 ป.4/3] ภาวะโลกร้อน (Global Warming)', 'medium', 'mcq', 'แก๊สเรือนกระจกที่เกิดจากการเผาไหม้เชื้อเพลิงและตัดไม้ทำลายป่า ซึ่งเป็นสาเหตุสำคัญของภาวะโลกร้อนคือแก๊สใด?', '["แก๊สออกซิเจน","แก๊สคาร์บอนไดออกไซด์","แก๊สไนโตรเจน","แก๊สฮีเลียม"]'::jsonb, 1, 'แก๊สคาร์บอนไดออกไซด์ทำหน้าที่ดักจับความร้อนในชั้นบรรยากาศ เมื่อมีปริมาณมากเกินไปจะทำให้อุณหภูมิเฉลี่ยของโลกสูงขึ้น'),
('สังคมศึกษา', 'ป.4', '[ส 5.2 ป.4/3] การมีส่วนร่วมในการอนุรักษ์สิ่งแวดล้อมในโรงเรียน', 'easy', 'mcq', 'นักเรียนสามารถช่วยประหยัดพลังงานในห้องเรียนได้อย่างไร?', '["เปิดแอร์อุณหภูมิ 16 องศาตลอดวัน","ปิดไฟและพัดลมทุกครั้งเมื่อไม่มีคนอยู่ในห้องเรียนหรือก่อนออกจากห้อง","เปิดน้ำทิ้งไว้ในห้องน้ำ","เสียบปลั๊กเครื่องใช้ไฟฟ้าค้างไว้ตลอดทั้งคืน"]'::jsonb, 1, 'การปิดสวิตช์ไฟ พัดลม และแอร์ทุกครั้งเมื่อไม่ใช้งาน ช่วยประหยัดพลังงานไฟฟ้าและลดค่าใช้จ่ายของโรงเรียน');
